package run.ikaros.sharing; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Mono; @RestController @RequestMapping("/api/v2/rooms/{roomId}/control") public class RoomControlController{private final RoomControlService service;public RoomControlController(RoomControlService s){service=s;}@PostMapping public Mono<RoomControlView> execute(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID roomId,@Valid@RequestBody ExecuteRoomControlCommandRequest r){return service.execute(a,roomId,r);}}
